CREATE TABLE IF NOT EXISTS token_usage (team_id VARCHAR(36), day_number BIGINT, member_id VARCHAR(36), run_key VARCHAR(36) DEFAULT '', provider VARCHAR(32), model VARCHAR(128), requests BIGINT DEFAULT 0 NOT NULL, unmetered_requests BIGINT DEFAULT 0 NOT NULL, input_tokens BIGINT DEFAULT 0 NOT NULL, cache_creation_tokens BIGINT DEFAULT 0 NOT NULL, cache_read_tokens BIGINT DEFAULT 0 NOT NULL, output_tokens BIGINT DEFAULT 0 NOT NULL, CONSTRAINT pk_token_usage PRIMARY KEY (team_id, day_number, member_id, run_key, provider, model), CONSTRAINT fk_token_usage_team_id__id FOREIGN KEY (team_id) REFERENCES teams(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT fk_token_usage_member_id__id FOREIGN KEY (member_id) REFERENCES members(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE INDEX token_usage_member ON token_usage (team_id, member_id, day_number);
